('BGR005', 'Zest Hotel Bogor', 'Bogor Tengah', 'Bogor', '../img/bogor5.jpg', 'Hotel budget dengan fasilitas memadai', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3963.347888567634!2d106.8025151!3d-6.59336!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69c5ce0e25ec59%3A0xc460980f0db7a22b!2zNsKwMzUnMzYuMSJTIDEwNsKwNDgnMTguMyJF!5e0!3m2!1sen!2sid!4v1620000000000!5m2!1sen!2sid', 420000.00, ''),
('BGR006', 'Bigland Hotel Bogor', 'Tanah Sareal', 'Bogor', '../img/bogor6.jpg', 'Hotel bisnis dengan meeting room yang luas. Menawarkan paket honeymoon khusus untuk pasangan baru menikah.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3963.185715326204!2d106.8031975!3d-6.5985698!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69c5df3f7c23df%3A0x46b334da0cfb4b78!2sBigland%20Hotel%20Bogor!5e0!3m2!1sen!2sid!4v1719253782180!5m2!1sen!2sid\n', 690000.00, ''),
('BGR007', 'Padjadjaran Suites Resort', 'Bogor Utara', 'Bogor', '../img/bogor7.jpg', 'Resort dengan konsep villa private. Setiap unit memiliki kolam renang pribadi dan taman tropis.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3976.1251634263767!2d106.7839072!3d-6.6402218!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69cf6f0dc8e659%3A0x4909580788467e73!2sPadjadjaran%20Suite%20Resort%20%26%20Convention%20Hotel!5e0!3m2!1sen!2sid!4v1719253912674!5m2!1sen!2sid\n', 770000.00, ''),
('BGR008', 'Hotel Salak The Heritage', 'Bogor Tengah', 'Bogor', '../img/bogor8.jpg', 'Hotel heritage dengan arsitektur kolonial Belanda. Terletak strategis di seberang Istana Bogor.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3963.344306912622!2d106.7914976!3d-6.5947114!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69c5b7d47f9df3%3A0x7a8423915ade7301!2sHotel%20Salak%20The%20Heritage!5e0!3m2!1sen!2sid!4v1719253996703!5m2!1sen!2sid\n', 650000.00, ''),
('BGR009', 'Favehotel Padjajaran Bogor', 'Bogor Timur', 'Bogor', '../img/bogor9.jpg', 'Hotel ekonomis dengan lokasi strategis dekat stasiun. Cocok untuk backpacker dan business trip singkat.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3963.2348220927775!2d106.8041758!3d-6.6029247!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69c5dcbaae6869%3A0x913b3c234e97e696!2sfavehotel%20Padjajaran%20Bogor!5e0!3m2!1sen!2sid!4v1719254080123!5m2!1sen!2sid\n', 480000.00, ''),
('BGR010', 'Hotel Santika Bogor', 'Bogor Tengah', 'Bogor', '../img/bogor10.jpg', 'Hotel dengan akses langsung ke mall terbesar di Bogor. Menawarkan promo paket menginap plus voucher belanja.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3963.2076021892444!2d106.8041383!3d-6.6010899!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69c5c4b2b2e479%3A0xe1897a1850562bb7!2sHotel%20Santika%20Bogor!5e0!3m2!1sen!2sid!4v1719254168436!5m2!1sen!2sid\n', 920000.00, ''),
