('BKS005', 'Ibis Styles Bekasi Jatibening', 'Jatibening', 'Bekasi', '../img/bekasi5.jpg', 'Hotel dengan desain unik dan nyaman', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3967.461866508801!2d106.9501235!3d-6.2521796!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e698dc3a491549f%3A0x5d73d468b3ebd040!2sIbis%20Styles%20Bekasi%20Jatibening!5e0!3m2!1sen!2sid!4v1719254731764!5m2!1sen!2sid\n', 670000.00, ''),
('BKS006', 'OYO 90255 Hotel Mega Putra', 'Mustikajaya', 'Bekasi', '../img/bekasi6.jpg', 'Penginapan budget dengan fasilitas dasar. Lokasi dekat dengan terminal bus dan pusat kuliner.', 'https://www.google.com/maps/embed?pb=!1m16!1m12!1m3!1d7930.683692630842!2d106.9859138!3d-6.2447369!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!2m1!1sOYO%20di%20bekasi!5e0!3m2!1sen!2sid!4v1719216600123!5m2!1sen!2sid\n', 190000.00, ''),
('BKS007', 'Grand Zuri Hotel Jababeka', 'Cikarang Utara', 'Bekasi', '../img/bekasi7.jpg', 'Hotel di kawasan industri dengan fasilitas lengkap. Menyediakan shuttle gratis ke pusat perbelanjaan terdekat.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.0569946714726!2d107.1457498!3d-6.2988941!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e698dc057238fe3%3A0x1fe75bdd73a00444!2sGrand%20Zuri%20Jababeka%20Cikarang%20by%20ZHM!5e0!3m2!1sen!2sid!4v1719254833511!5m2!1sen!2sid\n', 750000.00, ''),
('BKS008', 'Hotel Santika Mega City Bekasi', 'Bekasi Selatan', 'Bekasi', '../img/bekasi8.jpg', 'Hotel dengan konsep urban lifestyle. Terdapat rooftop bar dengan pemandangan kota Bekasi.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3967.4047435429835!2d106.9896696!3d-6.249769!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e698c3a996f3b5d%3A0x66c176db22e380fa!2sHotel%20Santika%20Mega%20City%20Bekasi!5e0!3m2!1sen!2sid!4v1719254929300!5m2!1sen!2sid\n', 620000.00, ''),
('BKS009', 'PrimeBiz Hotel Cikarang', 'Cikarang Selatan', 'Bekasi', '../img/bekasi9.jpg', 'Hotel bisnis di kawasan Cikarang. Menyediakan meeting room berteknologi tinggi dan business center.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.318116630255!2d107.1346838!3d-6.3162326!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e699ae59fac36b3%3A0x3c81a9670d1eba03!2sPrimebiz%20Hotel%20Cikarang!5e0!3m2!1sen!2sid!4v1719255028500!5m2!1sen!2sid\n', 560000.00, ''),
('BKS010', 'Axia South Cikarang', 'Cikarang', 'Bekasi', '../img/bekasi10.jpg', 'Hotel mewah dengan spa dan wellness center lengkap. Setiap kamar dilengkapi bath tub dan produk mandi premium.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.4903323374553!2d107.131423!3d-6.3279528!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e699af7c8e423f9%3A0x38c4d5cf364aa761!2sAXIA%20South%20Cikarang!5e0!3m2!1sen!2sid!4v1719255125434!5m2!1sen!2sid\n', 1350000.00, ''),
('DPK001', 'Margo Hotel', 'Margonda', 'Depok', '../img/depok1.jpg', 'Hotel strategis di Jalan Margonda', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3966.117781046153!2d106.8310671!3d-6.3719578!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69ec0e48e3fcef%3A0xa32b5205cfd6ef6!2sThe%20Margo%20Hotel%20Depok!5e0!3m2!1sen!2sid!4v1719255272986!5m2!1sen!2sid\n', 1050000.00, ''),
