('JKT004', 'The Westin Jakarta', 'Kuningan', 'Jakarta', '../img/hotel4.jpg', 'Hotel mewah di kawasan bisnis Kuningan', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3966.281882465787!2d106.8312858!3d-6.2237501!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f3f1144aa5e5%3A0x55b5886634b5a317!2sThe%20Westin%20Jakarta!5e0!3m2!1sen!2sid!4v1719255848600!5m2!1sen!2sid\n', 2800000.00, ''),
('JKT005', 'YELLO Hotel Harmoni', 'Harmoni', 'Jakarta', '../img/hotel5.jpg', 'Hotel modern dengan desain unik', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3967.6081163440384!2d106.8186827!3d-6.1642263!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f5d852f8965b%3A0x3b6b108581e9c8d1!2sYELLO%20Hotel%20Harmoni%20Jakarta!5e0!3m2!1sen!2sid!4v1719255887345!5m2!1sen!2sid\n', 520000.00, ''),
('JKT006', 'Mercure Jakarta Sabang', 'Sabang', 'Jakarta', '../img/hotel6.jpg', 'Hotel bintang 4 di kawasan bisnis Sabang. Dekat dengan pusat kuliner legendaris Jakarta.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3967.2468929627347!2d106.8224298!3d-6.1824567!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f42ebcafdcd9%3A0x846f378452a880d0!2sMercure%20Sabang!5e0!3m2!1sen!2sid!4v1719255960953!5m2!1sen!2sid\n', 940000.00, ''),
('JKT007', 'HARRIS Vertu Harmoni', 'Harmoni', 'Jakarta', '../img/hotel7.jpg', 'Hotel vertikal dengan nuansa industrial chic. Gym di lantai atas dengan view kota memukau.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3967.608977252784!2d106.8180765!3d-6.1642866!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f5d852f8965b%3A0xa2c3e2a867b3fc51!2sVertu%20Harmoni%20Jakarta!5e0!3m2!1sen!2sid!4v1719255989262!5m2!1sen!2sid\n', 1050000.00, ''),
('JKT008', 'Hotel Ciputra Jakarta', 'Grogol', 'Jakarta', '../img/hotel8.jpg', 'Hotel keluarga dengan fasilitas lengkap. Terhubung langsung dengan mall dan taman bermain anak.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3967.774081547439!2d106.783843!3d-6.168163!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f60404a5e893%3A0x6f9b862724e130c4!2sHotel%20Ciputra%20Jakarta!5e0!3m2!1sen!2sid!4v1719256012890!5m2!1sen!2sid', 880000.00, ''),
('JKT009', 'The Hermitage, a Tribute Portfolio Hotel', 'Menteng', 'Jakarta', '../img/hotel9.jpg', 'Boutique hotel dengan koleksi antik bernilai sejarah. Setiap sudut menceritakan masa lalu Jakarta.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3966.4148229275413!2d106.8355447!3d-6.1983176!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f415a4737463%3A0x94b231a525ce418a!2sThe%20Hermitage%2C%20a%20Tribute%20Portfolio%20Hotel%2C%20Jakarta!5e0!3m2!1sen!2sid!4v1719256041779!5m2!1sen!2sid\n', 2300000.00, ''),
('JKT010', 'Swiss-Belresidences Kalibata', 'Kalibata', 'Jakarta', '../img/hotel10.jpeg', 'Apartemen hotel dengan fasilitas resort. Cocok untuk keluarga maupun business trip jangka panjang.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3966.945143898233!2d106.8534645!3d-6.2555579!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e69f25521a557fd%3A0x32c4ffb8a0bef7f7!2sSwiss-Belresidences%20Kalibata%2C%20Jakarta!5e0!3m2!1sen!2sid!4v1719256068893!5m2!1sen!2sid\n', 690000.00, ''),
